import {entityIcon} from './entity-icons.js';
import {journalPlan,focusEntities,quarterYearProjects,quarterProjects} from './journal.js';
import {period} from './model.js';
import {projectArea,projectLabel,isProjectArchived,isProjectAvailable} from './domain.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
export function focusCount(state,p){return ['year','quarter'].includes(p.type)?focusEntities(state,p,'project').length:0;}
function entityChoice(state,plan,e,kind,frozen=false){
  const key=kind==='area'?'focusAreas':'focusProjects',selected=frozen||(plan[key]||[]).includes(e.id),label=kind==='project'?projectLabel(state,e.id)||e.name:e.name,area=kind==='project'?(e.areaName||state.areas.find(a=>a.id===projectArea(state,e))?.name||'Без зоны'):'';
  return `<div class="focus-entity ${selected?'is-focused':''}">${frozen?'<span class="focus-fixed-mark">◇</span>':`<button class="focus-select" data-action="select-focus" data-kind="${kind}" data-id="${esc(e.id)}" aria-pressed="${selected}" aria-label="${selected?'Убрать из фокуса: ':'В фокус: '}${esc(label)}">${selected?'✓':'+'}</button>`}<div><strong class="focus-entity-name">${entityIcon(e,kind)}${esc(frozen?e.name:label)}</strong>${area?`<small class="focus-project-path">${esc(area)} › ${esc(frozen?e.name:label)}</small>`:''}${e.description?`<p>${esc(e.description)}</p>`:''}</div>${!frozen?`<button class="text-button" data-action="edit-${kind}" data-id="${esc(e.id)}" aria-label="Настроить: ${esc(e.name)}">✎</button>`:''}</div>`;
}
function yearCatalog(state,plan){
 const groups=[...state.areas.map(a=>({id:a.id,name:a.name})),{id:null,name:'Без зоны'}];
 const catalog=groups.map(g=>{
  const projects=state.projects.filter(p=>!p.parentId&&isProjectAvailable(state,p)&&projectArea(state,p)===g.id);
  return `<section class="focus-group"><h3 class="year-area-heading">${esc(g.name)}</h3><div class="focus-group-projects">${projects.map(p=>entityChoice(state,plan,p,'project')).join('')}<button class="focus-add" data-action="new-project" data-area="${esc(g.id||'')}">+ Проект в зоне</button></div></section>`;
 }).join('');
 const stale=state.projects.filter(e=>plan.focusProjects.includes(e.id)&&(e.parentId||!isProjectAvailable(state,e)));
 return catalog+(stale.length?`<div class="quarter-focus-warning">В фокусе года остаются недоступные проекты или подпроекты. Уберите их перед фиксацией.</div>${stale.map(e=>entityChoice(state,plan,e,'project')).join('')}`:'');
}
export function focusPlannerHTML(state,p){
  if(p.type==='quarter')return quarterPlannerHTML(state,p);
  const plan=journalPlan(state,p),fixed=!!plan.snapshot,year=p.type==='year',projects=focusEntities(state,p,'project'),areas=focusEntities(state,p,'area');
  const choices=fixed?`<div class="fixed-focus-list">${projects.length?`<h3>Проекты в фокусе</h3>${projects.map(a=>entityChoice(state,plan,a,'project',true)).join('')}`:''}</div>`:year?yearCatalog(state,plan):`<div class="quarter-projects">${state.projects.filter(e=>!isProjectArchived(state,e)).map(e=>entityChoice(state,plan,e,'project')).join('')||'<p class="focus-empty">Создайте проект или начните с задач ниже.</p>'}</div>`;
  return `<section class="panel journal-focus" aria-label="${year?'Фокус года':'Фокусные проекты квартала'}"><div class="panel-header"><div class="panel-heading"><span class="heading-icon">◎</span><div><h2>${year?'Фокус года':'Фокусные проекты квартала'}</h2></div></div><div class="focus-heading-actions">${!fixed?`${year?'<button class="text-button" data-action="new-area">+ Зона</button>':''}<button class="secondary-button" data-action="new-project">+ Проект</button>`:''}<span class="badge ${fixed?'frozen':''}">${fixed?'◈ Зафиксирован':'Черновик'}</span></div></div>${year?`<div class="focus-block"><div class="focus-label">ФОКУС ГОДА</div>${fixed?`<div class="focus-text">${esc(plan.snapshot.goal||'—')}</div>`:`<textarea id="plan-goal" aria-label="Фокус года" maxlength="2000" placeholder="На чём хочу сосредоточиться в этом году?">${esc(plan.goal)}</textarea>`}</div>`:''}${choices}${year?`<div class="plan-footer">${fixed?`<div class="frozen-footer"><span>Фокус сохранён · ${date(plan.snapshot.at.slice(0,10))}</span><button class="text-button" data-action="export">Экспорт ↗</button><button class="text-button" data-action="unfreeze">Снять фиксацию</button></div>`:`<button class="primary-button wide" data-action="freeze" ${!focusCount(state,p)?'disabled':''}>◇ Зафиксировать фокус года</button><p class="button-caption">Сохранятся выбранные проекты и их названия.</p>`}</div>`:fixed?`<div class="focus-snapshot-caption">Выбор сохранён вместе с планом квартала · ${date(plan.snapshot.at.slice(0,10))}</div>`:''}</section>`;
}
function quarterPlannerHTML(state,p){
 const plan=journalPlan(state,p),fixed=!!plan.snapshot,annual=journalPlan(state,period('year',p.start)),parents=quarterYearProjects(state,p),annualIds=new Set(parents.map(e=>e.id)),eligible=new Set(quarterProjects(state,p).map(e=>e.id)),selected=focusEntities(state,p,'project');
 const choose=e=>`<button class="focus-select" data-action="select-focus" data-kind="project" data-id="${esc(e.id)}" aria-pressed="${plan.focusProjects.includes(e.id)}" aria-label="${plan.focusProjects.includes(e.id)?'Убрать из фокуса: ':'В фокус: '}${esc(e.name)}">${plan.focusProjects.includes(e.id)?'✓':'+'}</button>`;
 const catalog=parents.map(parent=>{
  const live=state.projects.find(e=>e.id===parent.id),active=live&&isProjectAvailable(state,live),children=state.projects.filter(e=>e.parentId===parent.id&&!annualIds.has(e.id)&&isProjectAvailable(state,e));
  return `<section class="quarter-branch"><div class="quarter-parent"><div><strong class="focus-entity-name">${entityIcon(parent,'project')}${esc(parent.name)}</strong><small>${!live?'Проект удалён':!active?'Завершён или в архиве':live.parentId?'Подпроект · второй уровень':'Проект из фокуса года'}</small></div>${!fixed&&active?choose(live):''}</div>${active?`<div class="quarter-children">${children.map(child=>fixed?`<div class="quarter-child-context">${entityIcon(child,'project')}${esc(child.name)}</div>`:entityChoice(state,plan,child,'project')).join('')}${!fixed&&!live.parentId?`<button class="focus-add" data-action="new-project" data-parent="${esc(live.id)}" data-area="${esc(projectArea(state,live)||'')}">+ Подпроект</button>`:''}</div>`:''}</section>`;
 }).join('');
 return `<div class="quarter-board"><section class="panel quarter-catalog-panel" aria-label="Проекты из фокуса года"><div class="panel-header"><div class="panel-heading"><div><h2>Фокус года · ${p.start.slice(0,4)}</h2><p>${annual.snapshot?'Зафиксированные проекты года':'Проекты из черновика года'}</p></div></div><button class="text-button" data-action="quarter-year">Открыть год ↗</button></div><div class="quarter-catalog-scroll" tabindex="0" aria-label="Годовые проекты и подпроекты">${catalog||'<div class="focus-empty">В фокусе года пока нет проектов. Выберите их на странице года, затем вернитесь к кварталу.</div>'}</div></section><section class="panel quarter-plan-panel" aria-label="Фокус квартала"><div class="panel-header"><div class="panel-heading"><div><h2>Фокус квартала</h2><p>Проекты и подпроекты на этот квартал</p></div></div><span class="badge ${fixed?'frozen':''}">${fixed?'Зафиксирован':'Черновик'}</span></div><div class="focus-block"><div class="focus-label">ФОКУС КВАРТАЛА</div>${fixed?`<div class="focus-text">${esc(plan.snapshot.goal||'—')}</div>`:`<textarea id="plan-goal" aria-label="Фокус квартала" maxlength="2000" placeholder="Какие результаты важны в этом квартале?">${esc(plan.goal)}</textarea>`}</div><div class="quarter-focus-scroll" tabindex="0" aria-label="Выбранные проекты квартала">${!fixed&&selected.some(e=>!eligible.has(e.id))?'<p class="quarter-focus-warning">Фокус года изменился. Уберите проекты вне годового фокуса перед фиксацией.</p>':''}${selected.length?selected.map(e=>entityChoice(state,plan,e,'project',fixed)).join(''):'<div class="focus-empty">Выберите проекты или их подпроекты из фокуса года.</div>'}</div><div class="plan-footer">${fixed?`<div class="frozen-footer"><span>Фокус сохранён · ${date(plan.snapshot.at.slice(0,10))}</span><button class="text-button" data-action="unfreeze">Снять фиксацию</button></div>`:`<button class="primary-button wide" data-action="freeze" ${!selected.length?'disabled':''}>Зафиксировать фокус квартала</button><p class="button-caption">Сохранятся выбранные проекты и их названия.</p>`}</div></section></div>`;
}
export function quarterStatsHTML(state,p){
 const plan=journalPlan(state,p),projects=focusEntities(state,p,'project'),groups=new Map();
 for(const project of projects){const name=project.areaName||state.areas.find(a=>a.id===project.areaId)?.name||'Без зоны';groups.set(name,(groups.get(name)||0)+1);}
 return `<div class="journal-stats-heading"><h2>Итоги квартала</h2><span>${plan.snapshot?'Зафиксированный фокус':'Предварительный фокус'}</span></div><div class="metrics focus-metrics"><div class="metric"><div class="metric-label">Проекты в фокусе</div><div class="metric-number">${projects.length}</div></div><div class="metric"><div class="metric-label">Из них подпроекты</div><div class="metric-number">${projects.filter(e=>e.parentId).length}</div></div><div class="metric"><div class="metric-label">Фиксация</div><div class="metric-number focus-state">${plan.snapshot?'Сохранён':'Черновик'}</div></div></div>${projects.length?`<section class="panel journal-chart"><h3>Фокус проектов по зонам</h3>${[...groups].map(([name,n])=>`<div class="focus-distribution"><span>${esc(name)}</span><div><i style="width:${n/projects.length*100}%"></i></div><b>${n}</b></div>`).join('')}</section>`:''}`;
}
export function yearStatsHTML(state,p){
  const plan=journalPlan(state,p),areas=focusEntities(state,p,'area'),projects=focusEntities(state,p,'project'),groups=new Map();
  for(const project of projects){const id=project.areaId,name=project.areaName||areas.find(a=>a.id===id)?.name||state.areas.find(a=>a.id===id)?.name||'Без зоны';groups.set(name,(groups.get(name)||0)+1);}
  return `<div class="journal-stats-heading"><h2>Итоги года</h2><span>${plan.snapshot?'Зафиксированный фокус':'Предварительный фокус'}</span></div><div class="metrics focus-metrics"><div class="metric"><div class="metric-label">Зоны в фокусе</div><div class="metric-number">${new Set(projects.map(p=>p.areaId||p.areaName||'Без зоны')).size}</div></div><div class="metric"><div class="metric-label">Проекты в фокусе</div><div class="metric-number">${projects.length}</div></div><div class="metric"><div class="metric-label">Фиксация</div><div class="metric-number focus-state">${plan.snapshot?'Сохранён':'Черновик'}</div></div></div>${projects.length?`<section class="panel journal-chart"><h3>Фокус проектов по зонам</h3>${[...groups].map(([name,n])=>`<div class="focus-distribution"><span>${esc(name)}</span><div><i style="width:${n/projects.length*100}%"></i></div><b>${n}</b></div>`).join('')}</section>`:''}`;
}
export function taskChartHTML(c,frozen){
  const cancelled=c.rows.filter(r=>r.live?.cancelled).length,open=c.total-c.done-cancelled;
  return `<section class="panel journal-chart"><h3>Выполнение ${frozen?'зафиксированного плана':'черновика'}</h3>${c.total?`<div class="completion-bar" role="img" aria-label="Выполнено ${c.done}, осталось ${open}, отменено ${cancelled}"><span class="completion-done" style="width:${c.done/c.total*100}%"></span><span class="completion-open" style="width:${open/c.total*100}%"></span><span class="completion-cancelled" style="width:${cancelled/c.total*100}%"></span></div><div class="completion-legend"><span><i class="completion-done"></i>Выполнено ${c.done}</span><span><i class="completion-open"></i>Осталось ${open}</span><span><i class="completion-cancelled"></i>Отменено ${cancelled}</span></div>`:'<p class="focus-empty">Добавьте задачи в план, чтобы видеть выполнение.</p>'}</section>`;
}
